import mongoose from 'mongoose';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

// Work delivered for a company - usually after an order. The company's own
// details stay on the company; the project references it, its customer record
// and the order it fulfils.
const projectSchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    projectNumber: { type: String, required: true, unique: true, immutable: true },
    name: { type: String, required: true, trim: true, maxlength: 200 },
    companyId: { type: ObjectId, ref: 'Company', required: true, index: true },
    // The company's customer record, filled in by the server when there is one.
    customerId: { type: ObjectId, ref: 'Customer', index: true },
    // The order this project delivers; must be the same company's.
    orderId: { type: ObjectId, ref: 'Order', index: true },
    description: { type: String, trim: true, maxlength: 5000 },
    startDate: { type: Date },
    expectedEndDate: { type: Date },
    actualEndDate: { type: Date },
    statusId: { type: ObjectId, ref: 'ProjectStatus', required: true, index: true },
    // From the administrator-managed priority list shared across the CRM.
    priorityId: { type: ObjectId, ref: 'LeadPriority', index: true },
    projectManagerId: { type: ObjectId, ref: 'User', index: true },
    teamMembers: [{ type: ObjectId, ref: 'User' }],
    budget: { type: Number, min: 0 },
    notes: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        companyId: 'company',
        customerId: 'customer',
        orderId: 'order',
        statusId: 'status',
        priorityId: 'priority',
        projectManagerId: 'projectManager',
        createdBy: 'createdByUser',
      },
    }),
  }
);

projectSchema.index({ teamMembers: 1 });
softDelete(projectSchema);

// Found by global search on these fields.
searchable(projectSchema, ['projectNumber', 'name']);

export default mongoose.model('Project', projectSchema);
